using System.IO;using System.Text;using System.Text.Json;using System.Data;using System.Windows;using System.Windows.Controls;using Microsoft.VisualBasic.FileIO;
class Program{
 static List<string[]> Parse(string text){using var p=new TextFieldParser(new StringReader(text)){TextFieldType=FieldType.Delimited,HasFieldsEnclosedInQuotes=true,TrimWhiteSpace=false};p.SetDelimiters(",");var rows=new List<string[]>();while(!p.EndOfData){var row=p.ReadFields()!;if(row.Length>100||rows.Count>=20000)throw new IOException("Limits: 100 columns, 20,000 rows");rows.Add(row);}return rows;}
 static List<string[]> Clean(List<string[]>rows)=>rows.Select(r=>r.Select(s=>s.Trim()).ToArray()).Where(r=>r.Any(s=>s.Length>0)).DistinctBy(r=>JsonSerializer.Serialize(r)).ToList();
 static string Encode(List<string[]>rows,bool safe)=>string.Join("\r\n",rows.Select(r=>string.Join(",",r.Select(v=>{var s=safe&&v.TrimStart().StartsWithAnyFormula()?"'"+v:v;return s.IndexOfAny(new[]{',','"','\r','\n'})>=0?"\""+s.Replace("\"","\"\"")+"\"":s;}))))+"\r\n";
 [STAThread]static int Main(string[]args){if(args.Contains("--self-test")){var sampleRows=Parse("a,\"b,c\"\r\nx,\"two\nlines\"\r\n");if(sampleRows[0][1]!="b,c"||Parse(Encode(sampleRows,false))[1][1]!="two\nlines")return 1;if(Clean(new(){new[]{" a ","b"},new[]{"a","b"},new[]{" ",""}}).Count!=1)return 1;return 0;}var app=new Application();var w=new Window{Title="CSV Cleanup Studio",Width=1100,Height=700};var root=new DockPanel{Margin=new Thickness(16)};w.Content=root;var bar=new StackPanel{Orientation=Orientation.Horizontal};DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);var path=new TextBox{Width=400,Margin=new Thickness(4)};bar.Children.Add(path);var safe=new CheckBox{Content="Spreadsheet-safe export",IsChecked=true,Margin=new Thickness(8)};bar.Children.Add(safe);var status=new TextBlock{Margin=new Thickness(8)};DockPanel.SetDock(status,Dock.Bottom);root.Children.Add(status);var grid=new DataGrid{IsReadOnly=true,AutoGenerateColumns=true};root.Children.Add(grid);var rows=new List<string[]>();void Draw(){var table=new DataTable();int width=rows.Select(r=>r.Length).DefaultIfEmpty(0).Max();for(int c=0;c<width;c++)table.Columns.Add("Column "+(c+1));foreach(var row in rows){var values=new object[width];for(int c=0;c<width;c++)values[c]=c<row.Length?row[c]:"";table.Rows.Add(values);}grid.ItemsSource=table.DefaultView;status.Text=$"{rows.Count} rows · {width} columns · {rows.Sum(r=>r.Count(string.IsNullOrWhiteSpace))} blank cells";}void Button(string name,Action fn){var b=new Button{Content=name,Padding=new Thickness(8),Margin=new Thickness(4)};bar.Children.Add(b);b.Click+=(_,_)=>{try{fn();Draw();}catch(Exception e)when(e is IOException or UnauthorizedAccessException or MalformedLineException or ArgumentException){MessageBox.Show(e.Message);}};}Button("Load",()=>{if(new FileInfo(path.Text).Length>2*1024*1024)throw new IOException("Limit: 2 MiB");rows=Parse(File.ReadAllText(path.Text));});Button("Trim / drop blank / deduplicate",()=>rows=Clean(rows));Button("Export CSV",()=>{var d=new Microsoft.Win32.SaveFileDialog{Filter="CSV|*.csv"};if(d.ShowDialog()==true)File.WriteAllText(d.FileName,Encode(rows,safe.IsChecked==true),new UTF8Encoding(false));});app.Run(w);return 0;}
}
static class Formula{public static bool StartsWithAnyFormula(this string s)=>s.Length>0&&"=+-@".Contains(s[0]);}
